            "type": "group"
          }
        },
        "priority": "Medium"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Task result data",
          "source": "=result",
          "var": "output",
          "properties": {
            "rejectionReason": { "type": "string" },
            "Action": { "type": "string", "enum": ["Approve", "Reject"], "default": "Approve" }
          }
        },
        "status": {
          "type": "string",
          "description": "Task completion status",
          "source": "=result.Action",
          "var": "status",
          "enum": ["Approve", "Reject"],
          "default": "Approve"
        }
      }
    },
    {
      "id": "logOutcome",
      "type": "core.action.script",
      "typeVersion": "1.1",
      "display": {
        "label": "Log Outcome"
      },
      "inputs": {
        "script": "const action = $vars.managerReview.status;\nconst expenseId = $vars.fetchExpense.output.expenseId;\nconst submitter = $vars.fetchExpense.output.submitter;\nconst amount = $vars.fetchExpense.output.amount;\nconst category = $vars.fetchExpense.output.category;\nconst rejectionReason = $vars.managerReview.output.rejectionReason;\nreturn { expenseId: expenseId, submitter: submitter, amount: amount, category: category, decision: action, rejectionReason: action === \"Reject\" ? (rejectionReason || \"\") : null };"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "done",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "Done"
      },
      "inputs": {}
